//! 📚️ Each roster retains its exact count, backing, partial row and typed published entries.
use super::*;
#[derive(Default,semio_framework_value::RetireOwned)]
#[value(crate="::semio_framework_value")]
struct Row{texts:[Option<String>;10],bytes:[Option<Vec<u8>>;2],numbers:[Option<u64>;2],field:OriginalCommandField,varint:OriginalCommandVarint,stage:u8}
impl Row{
 fn text(&mut self,source:&[u8],offset:&mut usize,index:usize,maximum:usize,cx:&mut StepContext<'_>)->Result<bool,OriginalTurnFailure>{if self.texts[index].is_some(){return Ok(true)}let turn=if self.field.bytes().is_some(){self.field.transfer_text_source_step(&mut self.texts[index],cx.retained_grant(),cx.fuel_remaining())}else{self.field.step(&mut OriginalBinarySlice::new(source,offset)?,maximum,true,cx.retained_grant(),cx.fuel_remaining())};debit(turn,cx)?;Ok(false)}
 fn bytes(&mut self,source:&[u8],offset:&mut usize,index:usize,maximum:usize,cx:&mut StepContext<'_>)->Result<bool,OriginalTurnFailure>{if self.bytes[index].is_some(){return Ok(true)}let turn=if self.field.bytes().is_some(){self.field.transfer_bytes_source_step(&mut self.bytes[index],cx.retained_grant(),cx.fuel_remaining())}else{self.field.step(&mut OriginalBinarySlice::new(source,offset)?,maximum,false,cx.retained_grant(),cx.fuel_remaining())};debit(turn,cx)?;Ok(false)}
 fn number(&mut self,source:&[u8],offset:&mut usize,index:usize,cx:&mut StepContext<'_>)->Result<bool,OriginalTurnFailure>{if self.numbers[index].is_some(){return Ok(true)}let turn=if self.varint.value().is_some(){self.varint.transfer_source_step(&mut self.numbers[index],cx.retained_grant(),cx.fuel_remaining())}else{self.varint.step(&mut OriginalBinarySlice::new(source,offset)?,cx.retained_grant(),cx.fuel_remaining())};debit(turn,cx)?;Ok(false)}
 fn t(&mut self,index:usize)->String{self.texts[index].take().unwrap()}
}
pub(super) fn reserve<T>(output:&mut Vec<T>,count:usize,reserved:&mut bool,cx:&mut StepContext<'_>)->Result<bool,OriginalTurnFailure>{
 if *reserved{return Ok(true)}if output.capacity()!=0||!output.is_empty(){return Err(invalid("AppFrame roster must start in its actual empty destination"))}let capacity=count.checked_mul(size_of::<T>()).ok_or_else(||invalid("AppFrame roster backing extent overflow"))?;let copy=size_of::<Vec<T>>()+size_of::<bool>();let grant=cx.retained_grant();if cx.fuel_remaining()<1||!retained_clone_grant_admits(grant,Demand{copy_bytes:copy,capacity_bytes:capacity,depth:1,..Default::default()}){return Ok(false)}
 output.try_reserve_exact(count).map_err(|_|ValueError::literal(ValueRefusalKind::AllocationFailed,"AppFrame roster backing allocation failed"))?;*reserved=true;cx.consume_fuel(1);cx.consume_retained(Progress{copied_items:1,copied_bytes:copy,retained_capacity_bytes:output.capacity()*size_of::<T>(),..Default::default()})?;Ok(false)
}
#[derive(Default,semio_framework_value::RetireOwned)]
#[value(crate="::semio_framework_value")]
pub(super) struct List{kind:Option<u8>,count:Option<u64>,varint:OriginalCommandVarint,reserved:bool,done:bool,row:Row,causal:causal::Envelope,archive_stage:u8}
impl List{
 fn enter(&mut self,kind:u8,cx:&mut StepContext<'_>)->Result<bool,OriginalTurnFailure>{if self.kind==Some(kind){return Ok(true)}if self.kind.is_some()&&!self.done{return Err(invalid("AppFrame roster changed while its actual row remained pending"))}if !pay(cx,size_of::<Self>(),1)?{return Ok(false)}*self=Self{kind:Some(kind),..Self::default()};Ok(false)}
 fn count(&mut self,source:&[u8],offset:&mut usize,maximum:usize,cx:&mut StepContext<'_>)->Result<bool,OriginalTurnFailure>{if let Some(count)=self.count{if count>maximum as u64{return Err(invalid("AppFrame roster exceeds its declared entry count"))}return Ok(true)}let turn=if self.varint.value().is_some(){self.varint.transfer_source_step(&mut self.count,cx.retained_grant(),cx.fuel_remaining())}else{self.varint.step(&mut OriginalBinarySlice::new(source,offset)?,cx.retained_grant(),cx.fuel_remaining())};debit(turn,cx)?;Ok(false)}
 fn finish(&mut self,cx:&mut StepContext<'_>)->Result<bool,OriginalTurnFailure>{if self.done{return Ok(true)}if pay(cx,size_of::<bool>(),1)?{self.done=true}Ok(false)}
 pub fn advance(&mut self,source:&[u8],offset:&mut usize,data:&mut Fields,kind:u8,limits:NativeAppFrameLimits,cx:&mut StepContext<'_>)->Result<bool,OriginalTurnFailure>{
  if !self.enter(kind,cx)?{return Ok(false)}if self.done{return Ok(true)}if !self.count(source,offset,limits.maximum_entries,cx)?{return Ok(false)}let count=self.count.unwrap()as usize;
  let ready=match kind{0=>reserve(&mut data.envelopes,count,&mut self.reserved,cx)?,1=>reserve(&mut data.children,count,&mut self.reserved,cx)?,2=>reserve(&mut data.local_ops,count,&mut self.reserved,cx)?,3=>reserve(&mut data.foreign,count,&mut self.reserved,cx)?,4=>reserve(&mut data.windows,count,&mut self.reserved,cx)?,5=>reserve(&mut data.heads,count,&mut self.reserved,cx)?,_=>unreachable!()};if !ready{return Ok(false)}
  let length=match kind{0=>data.envelopes.len(),1=>data.children.len(),2=>data.local_ops.len(),3=>data.foreign.len(),4=>data.windows.len(),5=>data.heads.len(),_=>unreachable!()};if length==count{return self.finish(cx)}
  if kind==0{if !self.causal.advance(source,offset,limits,cx)?{return Ok(false)}if !pay(cx,size_of::<causal::Envelope>()+size_of::<protocol::causal::MutationEnvelope>()+size_of::<Vec<protocol::causal::MutationEnvelope>>(),1)?{return Ok(false)}data.envelopes.push(self.causal.take());return Ok(false)}
  let row=&mut self.row;let stage=row.stage;
  let ready=match kind{2|3=>row.bytes(source,offset,0,limits.maximum_field_bytes,cx)?,1|5=>match stage{0..=2=>row.text(source,offset,stage as usize,limits.maximum_field_bytes,cx)?,3=>row.bytes(source,offset,0,limits.maximum_field_bytes,cx)?,4=>row.text(source,offset,3,limits.maximum_field_bytes,cx)?,_=>true},4=>match stage{0|1=>row.text(source,offset,stage as usize,limits.maximum_field_bytes,cx)?,2=>row.bytes(source,offset,0,limits.maximum_field_bytes,cx)?,_=>true},_=>unreachable!()};
  if !ready{return Ok(false)}let terminal=match kind{1|5=>5,4=>3,_=>0};if stage<terminal{if pay(cx,size_of::<u8>(),1)?{row.stage+=1}return Ok(false)}
  let entry=match kind{1=>size_of::<ChildPackEntry>(),5=>size_of::<ChildHeadPackEntry>(),4=>size_of::<WindowConfigPackEntry>(),_=>size_of::<Vec<u8>>()};if !pay(cx,size_of::<Row>()+entry+size_of::<Vec<Vec<u8>>>(),1)?{return Ok(false)}
  match kind{1=>data.children.push(ChildPackEntry{slot:row.t(0),child_id:row.t(1),dialect:row.t(2),envelope_pack:row.bytes[0].take().unwrap(),owner:row.t(3)}),5=>data.heads.push(ChildHeadPackEntry{slot:row.t(0),child_id:row.t(1),dialect:row.t(2),head_pack:row.bytes[0].take().unwrap(),owner:row.t(3)}),4=>data.windows.push(WindowConfigPackEntry{window_id:row.t(0),window_kind_id:row.t(1),envelope_pack:row.bytes[0].take().unwrap()}),2=>data.local_ops.push(row.bytes[0].take().unwrap()),3=>data.foreign.push(row.bytes[0].take().unwrap()),_=>unreachable!()}*row=Row::default();Ok(false)
 }
 pub fn archive(&mut self,source:&[u8],offset:&mut usize,archive:&mut DocumentArchivePack,limits:NativeAppFrameLimits,cx:&mut StepContext<'_>)->Result<bool,OriginalTurnFailure>{
  if !self.enter(6,cx)?{return Ok(false)}if self.done{return Ok(true)}
  if self.archive_stage<2{let stage=self.archive_stage as usize;if !self.row.bytes(source,offset,stage,limits.maximum_field_bytes,cx)?{return Ok(false)}if pay(cx,2*size_of::<Vec<u8>>()+size_of::<u8>(),1)?{if stage==0{archive.parent_pack=self.row.bytes[stage].take().unwrap()}else{archive.parent_spr=self.row.bytes[stage].take().unwrap()}self.archive_stage+=1}return Ok(false)}
  if !self.count(source,offset,limits.maximum_entries.min(1024),cx)?{return Ok(false)}let count=self.count.unwrap()as usize;if !reserve(&mut archive.members,count,&mut self.reserved,cx)?{return Ok(false)}if archive.members.len()==count{return self.finish(cx)}
  let row=&mut self.row;let stage=row.stage;let ready=match stage{0=>row.number(source,offset,0,cx)?,1..=10=>row.text(source,offset,(stage-1)as usize,limits.maximum_field_bytes,cx)?,11=>row.bytes(source,offset,0,limits.maximum_field_bytes,cx)?,_=>true};if !ready{return Ok(false)}if row.numbers[0].is_some_and(|n|n>u32::MAX as u64){return Err(invalid("AppFrame archive ordinal exceeds u32"))}
  if stage<12{if pay(cx,size_of::<u8>(),1)?{row.stage+=1}return Ok(false)}
  if !pay(cx,size_of::<Row>()+size_of::<OwnedDocumentMemberPackEntry>()+size_of::<Vec<OwnedDocumentMemberPackEntry>>(),1)?{return Ok(false)}
  archive.members.push(OwnedDocumentMemberPackEntry{ordinal:row.numbers[0].take().unwrap()as u32,reference:DocumentArchiveArtifactRef{artifact_id:row.t(0),artifact_kind:row.t(1),standard:row.t(2),subset:row.t(3)},owner:DocumentArchiveOwnerRef{parent:DocumentArchiveArtifactRef{artifact_id:row.t(4),artifact_kind:row.t(5),standard:row.t(6),subset:row.t(7)},slot:row.t(8),child_id:row.t(9)},envelope_pack:row.bytes[0].take().unwrap()});*row=Row::default();Ok(false)
 }
}
